window.ScripturaLexicons.BDAG_PART_0182 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0182-01\" data-source=\"BDAG\" data-search=\"καθίστημι verbo levar; designar; estabelecer; tornar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθίστημι</td><td>verbo</td><td>levar; designar; estabelecer; tornar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0182-02\" data-source=\"BDAG\" data-search=\"καθό advérbio conforme; na medida em que BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθό</td><td>advérbio</td><td>conforme; na medida em que</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0182-03\" data-source=\"BDAG\" data-search=\"καθολικός, ή, όν adjetivo geral; universal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθολικός, ή, όν</td><td>adjetivo</td><td>geral; universal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0182-04\" data-source=\"BDAG\" data-search=\"καθόλου advérbio inteiramente; absolutamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθόλου</td><td>advérbio</td><td>inteiramente; absolutamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0182-05\" data-source=\"BDAG\" data-search=\"καθοπλίζω verbo médio armar-se; equipar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθοπλίζω</td><td>verbo médio</td><td>armar-se; equipar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0182-06\" data-source=\"BDAG\" data-search=\"καθοράω verbo perceber; notar; discernir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθοράω</td><td>verbo</td><td>perceber; notar; discernir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0182-07\" data-source=\"BDAG\" data-search=\"καθότι conjunção na medida em que; porque; como BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθότι</td><td>conjunção</td><td>na medida em que; porque; como</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0182-08\" data-source=\"BDAG\" data-search=\"καθώς advérbio; conjunção assim como; conforme; visto que; quando BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθώς</td><td>advérbio; conjunção</td><td>assim como; conforme; visto que; quando</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0182-09\" data-source=\"BDAG\" data-search=\"καθώσπερ advérbio assim como BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθώσπερ</td><td>advérbio</td><td>assim como</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0182-10\" data-source=\"BDAG\" data-search=\"καί conjunção; advérbio e; também; até; ainda; contudo; isto é BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καί</td><td>conjunção; advérbio</td><td>e; também; até; ainda; contudo; isto é</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0182-11\" data-source=\"BDAG\" data-search=\"Καϊάφας, α, ὁ nome próprio masculino Caifás; sumo sacerdote BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Καϊάφας, α, ὁ</td><td>nome próprio masculino</td><td>Caifás; sumo sacerdote</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0182-12\" data-source=\"BDAG\" data-search=\"καίγε partícula; remissão ver γέ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καίγε</td><td>partícula; remissão</td><td>ver γέ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0182-13\" data-source=\"BDAG\" data-search=\"Κάϊν, ὁ nome próprio masculino Caim; filho de Adão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κάϊν, ὁ</td><td>nome próprio masculino</td><td>Caim; filho de Adão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0182-14\" data-source=\"BDAG\" data-search=\"Καϊνάμ, ὁ nome próprio masculino Cainã; dois personagens genealógicos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Καϊνάμ, ὁ</td><td>nome próprio masculino</td><td>Cainã; dois personagens genealógicos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0182-15\" data-source=\"BDAG\" data-search=\"καινίζω verbo tornar novo; renovar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καινίζω</td><td>verbo</td><td>tornar novo; renovar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0182-16\" data-source=\"BDAG\" data-search=\"καινοποιέω verbo renovar; fazer novo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καινοποιέω</td><td>verbo</td><td>renovar; fazer novo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0182-17\" data-source=\"BDAG\" data-search=\"καινός, ή, όν adjetivo novo; inusitado; renovado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καινός, ή, όν</td><td>adjetivo</td><td>novo; inusitado; renovado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0182-18\" data-source=\"BDAG\" data-search=\"καινότης, ητος, ἡ substantivo feminino novidade; vida nova BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καινότης, ητος, ἡ</td><td>substantivo feminino</td><td>novidade; vida nova</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0182-19\" data-source=\"BDAG\" data-search=\"καινοφωνία remissão lexical ver κενοφωνία BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καινοφωνία</td><td>remissão lexical</td><td>ver κενοφωνία</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0182-20\" data-source=\"BDAG\" data-search=\"καινῶς advérbio de modo novo; recentemente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καινῶς</td><td>advérbio</td><td>de modo novo; recentemente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0182-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθίστημι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">/ <span class=\"greek\">καθιστάνω</span> ( <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:15</a> ; 1 Cl 42:4 ; EpArist 280 ; 281 ; Jos. , Ant. 16, 129 ; POxf 16, 12). Presente, 3ª pessoa do singular <span class=\"greek\">καθιστᾷ</span> Da 2:21 Theod. ; imperfeito <span class=\"greek\">καθίστα</span> ( Just ., D . 52, 3); particípio <span class=\"greek\">καθιστῶν</span> LXX ; futuro <span class=\"greek\">καταστήσω</span> ; 1º aoristo <span class=\"greek\">κατέστησα</span> ; perfeito <span class=\"greek\">καθέστακα</span> LXX ; intransitivo <span class=\"greek\">καθέστηκα</span> LXX ; mais-que-perfeito - <span class=\"greek\">κεισαν</span> ( 3 Macc 2:33 ). Passivo: 1º futuro <span class=\"greek\">κατασταθήσομαι</span> ; 1º aoristo <span class=\"greek\">καθεστάθην</span> ; particípio perfeito <span class=\"greek\">καθεσταμένος</span> ( LXX ; 1 Cl 54:2 ; Jos. , Ant. 12, 268 ) (ver <span class=\"greek\">κατά</span> e <span class=\"greek\">ἵστημι</span> ; Homero e posteriores).</p><p class=\"entry-text\">① levar alguém a algum lugar, conduzir, transportar ( Od . 13, 274; Thu . 4, 78, 6; X. , An. 4, 8, 8; UPZ 78, 14 [159 b.c. ]; BGU 93, 22 <span class=\"greek\">κατάστησον</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Μέμφιν</span> ; Josh 6:23 ; 1 Km 5:3 ; 2 Ch 28:15 ; Jos. , Ant. 7, 279 ; uso reflexivo em Tat . 2, 1 <span class=\"greek\">τίς</span> … <span class=\"greek\">ἀλαζονείας</span> <span class=\"greek\">ἔξω</span> <span class=\"greek\">καθέστηκεν</span>; =quem esteve livre de vanglória?) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:15</a>.</p><p class=\"entry-text\">② atribuir a alguém uma posição de autoridade, nomear, colocar à frente de ( Hdt. et al. )</p><p class=\"entry-text\">ⓐ alguém à frente de algo ou de outra pessoa <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινος</span> ( Arrian , Exp. Al. 3, 6, 6 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">χρημάτων</span> ; Gen 41:41 ; Num 3:10 ; Da 2:48 ; Jos. , Ant. 2, 73 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:45</a> ; cf. 25:21, 23 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:42</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:3</a>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span> sobre alguma coisa ( Jos. , Ant. 12, 278 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:47</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:44</a>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span> ( Isocr . 12, 132; X. , Cyr. 8, 1, 9; Da 3:12 Theod. ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:7</a> variante de leitura ( Ps 8:7 ). Com acusativo de pessoa e infinitivo de finalidade <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">κατέστησε</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀγγέλους</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">συντηρεῖν</span> <span class=\"greek\">αὐτούς</span> Hs 5, 6, 2 .</p><p class=\"entry-text\">ⓑ com acusativo: autorizar, nomear ( Pla ., Rep. 10, 606d <span class=\"greek\">ἄρχοντα</span> ; Vi. Aesopi W 15 p. 83 P.; 1 Macc 3:55 ; Jos. , Ant. 9, 4 <span class=\"greek\">κρίτας</span> ; Just ., D . 52, 3 <span class=\"greek\">βασιλεῖς</span> ) <span class=\"greek\">πρεσβυτέρους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:5</a>. Cf. 1 Cl 42:5 (em lugar de <span class=\"greek\">δώσω</span> Is 60:17 ; esta última leitura Iren. 4, 26, 5 [ Harv. II 238]); 43:1; 44:2. Passivo 44:3; 54:2; seguido de <span class=\"greek\">εἰς</span> com infinitivo, referente ao sumo sacerdote: <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">προσφέρειν</span> <span class=\"greek\">δῶρα</span> <span class=\"greek\">καθίσταται</span> é designado para oferecer dons <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:3</a>. Semelhantemente <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">καθίσταται</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>, <span class=\"greek\">ἵνα</span> <span class=\"greek\">προσφέρῃ</span> é designado para atuar em favor dos homens nas coisas referentes a Deus, para oferecer <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:1</a>. —Um segundo acusativo (predicativo) pode acompanhar <span class=\"greek\">τινά</span>: fazer de alguém alguma coisa ou nomeá-lo para certo cargo ( Hdt. 7, 105 al. ; PHib 82 I, 14 [239/238 b.c. ]; Sir 32:1 ; 1 Macc 9:25 ; 10:20 ; Jos. , Ant. 12, 360 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:14</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:10</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:28</a> ( Diog. L. 9, 64 <span class=\"greek\">ἀρχιερέα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">αὐτόν</span> ). <span class=\"greek\">τίς</span> <span class=\"greek\">σε</span> <span class=\"greek\">κατέστησεν</span> <span class=\"greek\">ἄρχοντα</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:27</a>, 35 ; 1 Cl 4:10 (as três passagens de Ex 2:14 ).—Com <span class=\"greek\">εἰς</span> : <span class=\"greek\">εἰς</span> <span class=\"greek\">ἐπισκόπους</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">διακόνους</span> 1 Cl 42:4 ( Just ., D . 65:7).</p><p class=\"entry-text\">③ fazer alguém experimentar alguma coisa, tornar, causar <span class=\"greek\">τινά</span> <span class=\"greek\">τι</span> ( Eur ., Androm. 635 <span class=\"greek\">κλαίοντά</span> <span class=\"greek\">σε</span> <span class=\"greek\">καταστήσει</span> ; Pla ., Phlb. 16b <span class=\"greek\">ἐμὲ</span> <span class=\"greek\">ἔρημον</span> <span class=\"greek\">κατέστησεν</span> ; POxy 939, 19 <span class=\"greek\">σε</span> <span class=\"greek\">εὐθυμότερον</span> ; Jos. , Ant. 6, 92 ; 20, 18 ; Just ., A I, 33, 6 <span class=\"greek\">τὴν</span> <span class=\"greek\">παρθένον</span> … <span class=\"greek\">ἐγκύμονα</span> <span class=\"greek\">κατέστησε</span> ) <span class=\"greek\">ταῦτα</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀργοὺς</span> <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">ἀκάρπους</span> <span class=\"greek\">καθίστησιν</span> isto não vos torna inúteis nem infrutíferos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:8</a>. —Passivo ser feito, tornar-se ( Menand ., Fgm. 769 K.=483 Kö. <span class=\"greek\">ἅπαντα</span> <span class=\"greek\">δοῦλα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">φρονεῖν</span> <span class=\"greek\">καθίσταται</span> ; Herodas 1, 40 <span class=\"greek\">ἱλαρὴ</span> <span class=\"greek\">κατάστηθι</span> =ficar alegre; Diod S 17, 70, 3; <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 5; PRein 18, 40 [108 b.c. ] <span class=\"greek\">ἀπερίσπαστος</span> <span class=\"greek\">κατασταθήσεται</span> = «permanecer sem perturbação’; EpArist 289 <span class=\"greek\">σκληροὶ</span> <span class=\"greek\">καθίστανται</span> ; Philo , Aet. M. 133 ) <span class=\"greek\">ἁμαρτωλοὶ</span> <span class=\"greek\">κατεστάθησαν</span> … <span class=\"greek\">δίκαιοι</span> <span class=\"greek\">κατασταθήσονται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:19</a> (FDanker in Gingrich Festschr. ’72, 106f, citando POxy 281, 14–24 [20–50 a.d. ] num possível sentido jurídico; cf. PTebt 183; mas cf. Cat. Cod. Astr. IX/2 p. 132, 12 referente à recuperação de uma condição saudável). As duas passagens de Tiago nas quais ocorre a palavra provavelmente também pertencem a esta acepção (<span class=\"greek\">φίλος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κόσμου</span>) <span class=\"greek\">ἐχθρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">καθίσταται</span> 4:4 ; cf. 3:6, onde o texto talvez apresente problemas.—JdeZwaan, Rö 5:19; Jk 3:6; 4:4 en de <span class=\"greek\">Κοινή</span> : TSt 31, 1913, 85–94.—Texto reconstituído Hs 10, 3, 4 ( POxy 404 recto, 19) (ver <span class=\"greek\">καθαρότης</span> ).— DELG sob o verbete <span class=\"greek\">ἵστημι</span> . M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0182-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθό</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">advérbio ( Pla . et al. ; ins , pap , LXX ; Jos. , Ant. 16, 26 ; Tat . 5:1; Mel. , P. 9, linhas 60–67; Ath. )= <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὅ</span> . (assim, por exemplo , schol. to Pla . 181e= «assim como»)</p><p class=\"entry-text\">① marcador de semelhança: como, assim como ( Michel 731, 22 [II b.c. ] <span class=\"greek\">καθὸ</span> <span class=\"greek\">πάτριόν</span> <span class=\"greek\">ἐστιν</span> ; EpArist 11 ) como <span class=\"greek\">κ</span>. <span class=\"greek\">δεῖ</span> como convém, como se deve <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:26</a> ( cf. Diod S 8, 15, 1 <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀξίαν</span> <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">θελήσαντες</span> <span class=\"greek\">δυνάμεθα</span> <span class=\"greek\">τιμῆσαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δαιμόνιον</span> =não podemos honrar a divindade de maneira digna, ainda que o desejemos [fazer]).</p><p class=\"entry-text\">② marcador de grau: na medida em que, até o ponto em que <span class=\"greek\">καθὸ</span> <span class=\"greek\">κοινωνεῖτε</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">παθήμασιν</span> na medida em que participais dos sofrimentos de Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:13</a>. <span class=\"greek\">καθὸ</span> <span class=\"greek\">ἐὰν</span> <span class=\"greek\">ἔχῃ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:12a</a> ; cf. o versículo 12b. — M-M .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0182-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθολικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( <span class=\"greek\">κατά</span> + <span class=\"greek\">ὅλος</span> ; Hippocr . et al. ; Polyb .; Dionys. Hal., Comp . Verb. 12; Iambl ., Vi. Pyth. 15, 65; Porphyr., Vi. Pyth. 30; Ps.-Plut ., Hom . 201 <span class=\"greek\">κ</span>. <span class=\"greek\">λόγοι</span> ; SIG 785, 4 [6 b.c. ]; OGI 668, 47; BGU 19 I, 5 [135 a.d. ]; Philo ; Just ., D . 102, 4 <span class=\"greek\">καθολικὰς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μερικὰς</span> <span class=\"greek\">κρίσεις</span> «juízos gerais e particulares»; Ath. 27, 1; <span class=\"greek\">κ</span>. <span class=\"greek\">ἀνάστασις</span> <span class=\"greek\">ἁπάντων</span> <span class=\"greek\">ἀνθρώπων</span> Theoph. Ant. 1, 13 [p. 86, 24]. Posteriormente, um título muito empregado) geral, universal <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐκκλησία</span> a assembleia/igreja universal (em contraste com uma congregação particular [ cf. o contraste <span class=\"greek\">μερικὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">καθολικά</span> em Zósimo 7: Hermetica IV p. 105, 24]; ver Hdb., sobre ISm 8:2 ) ISm 8:2 ; MPol ins ; 8:1; 19:2. Não em contraste com uma congregação particular MPol 16:2 ; mas o texto é incerto. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐκκλησιαστικὸς</span> <span class=\"greek\">κανὼν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κ</span> . ( Artem . 1, 2 p. 4, 23 <span class=\"greek\">ὅρος</span> <span class=\"greek\">κ</span> .=uma definição de validade geral; 4, 2 p. 205, 1 <span class=\"greek\">λόγος</span> ; Aëtius p. 30, 20 referente a uma lei de validade geral; Herm. Wr. 2 ins variante de leitura <span class=\"greek\">Ἑρμοῦ</span> … <span class=\"greek\">λόγος</span> <span class=\"greek\">καθολικός</span> ; Epict . 4, 4, 29; 4, 12, 7 <span class=\"greek\">τὰ</span> <span class=\"greek\">καθολικά</span> = as leis ou verdades de validade geral) EpilMosq 2. <span class=\"greek\">Ἐπιστολὴ</span> <span class=\"greek\">καθολικά</span> ( <span class=\"greek\">καθολικὴ</span> <span class=\"greek\">ἐπιστολή</span> atestado primeiramente no antimontanista Apolônio [c. 197 d.C.] em Eusébio , HE 5, 18, 5. O próprio Eusébio fala, como nós, das «sete» epístolas gerais: 2, 23, 25) como variante de leitura no sobrescrito de Tiago; 1 e 2 Pt; 1–3 J; e Judas.— M-M . TW . Sv .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0182-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθόλου</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">advérbio (grego antigo : Demosth . et al. [ B-D-F § 225 ; também 12, 3]; ins , pap , LXX , EpArist ; Jos. , Bell. 4, 460 ; 5, 390 , Ant. 4, 286 ; Just .) inteiramente, completamente, <span class=\"greek\">μὴ</span> <span class=\"greek\">κ</span> . de modo nenhum ( Sb 4369a, 36; Ex 22:10 variante de leitura ) <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μὴ</span> <span class=\"greek\">φθέγγεσθαι</span> não falar absolutamente nada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:18</a> (ver B-D-F § 399, 3 ; Ezk 13:3 ; TestGad 5:5 . <span class=\"greek\">μηδὲν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">καθόλου</span> <span class=\"greek\">λαβεῖν</span> : BGU 1058, 25; 1106, 24; 1165, 24 [todos do século I a.C. ]). <span class=\"greek\">κ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">βλέπειν</span> Papias ( 3:2 [não as seções g e h]).— M-M . Sv .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0182-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθοπλίζω</h1><div class=\"entry-meta\"><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver <span class=\"greek\">ὁπλίζω</span> e <span class=\"greek\">ὅπλον</span> ; Soph . et al. ; a voz ativa no sentido de «armar completamente, equipar» X. et al. ; LXX ; EpArist 14 ; Jos. , Ant. 2, 341 ) na literatura aqui considerada, voz média <span class=\"greek\">καθοπλίζομαι</span> particípio do 1º aoristo <span class=\"greek\">καθοπλισάμενος</span> ; particípio perfeito passivo <span class=\"greek\">καθωπλισμένος</span> ( PGM 13, 528; 4 Macc 4:10 ; 7:11 ; Jos. , Ant. 5, 244 ; Tat . 16:2 [sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:14</a> ]) armar-se com armas, armar-se, equipar-se ( Polyb . 3, 62, 7 al. ; 4 Macc 3:12 ).</p><p class=\"entry-text\">ⓐ literalmente <span class=\"greek\">ὁ</span> <span class=\"greek\">ἰσχυρὸς</span> <span class=\"greek\">καθωπλισμένος</span> o homem forte, armado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:21</a>.</p><p class=\"entry-text\">ⓑ figuradamente ( Diod S 9, 1, 4 referindo-se a almas equipadas com [a] armadura [da legislação de Sólon]; 4 Macc 11:22 ) <span class=\"greek\">καθωπλίσασθαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">φόβον</span> <span class=\"greek\">κυρίου</span> armar-se com o temor de Deus Hm 12, 2, 4 . <span class=\"greek\">καθωπλισμένος</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">φόβῳ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> ibid. — DELG sob o verbete <span class=\"greek\">ὅπλον</span> . M-M .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0182-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθοράω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">infinitivo futuro <span class=\"greek\">κατόψεσθαι</span> ( Just .); infinitivo aoristo <span class=\"greek\">κατιδεῖν</span> ( Just ., D . 2, 4) ( Hom . et al. ; Abercius Ins . 5; PLond II, 342, 13 p. 174; LXX ) perceber, notar, inclusive na percepção interior ( Pind ., P. 9, 49; Aristot ., Rhet. 3, 9 <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">πάντες</span> <span class=\"greek\">βούλονται</span> <span class=\"greek\">καθορᾶν</span> ; Philostrat ., Vi. Soph . 1, 22 p. 38, 10 al. ; 3 Macc 3:11 ; Philo ; Jos. , Ant. 8, 168 ; Just .; Tat . 13, 2) <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀόρατα</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ποιήμασι</span> <span class=\"greek\">νοούμενα</span> <span class=\"greek\">καθοράται</span> os atributos invisíveis de Deus são percebidos pelos olhos da razão nas coisas criadas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:20</a> (sobre o jogo de palavras, cf. Ps.-Aristot ., De Mundo 399b, 14ff <span class=\"greek\">ἀόρατος</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἔργοις</span> <span class=\"greek\">ὁρᾶται</span> ; SibOr 4, 12 <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">καθορῶν</span> <span class=\"greek\">ἅμα</span> <span class=\"greek\">πάντας</span> <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">οὐδενὸς</span> <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">ὁρᾶται</span> .— Philostrat ., Ep. 41 <span class=\"greek\">νοῦς</span> <span class=\"greek\">ὁρῇ</span> ).— DELG sob o verbete <span class=\"greek\">ὁράω</span> . M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0182-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθότι</h1><div class=\"entry-meta\"><span>conjunção</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( Hdt. , Thu .+; ins , pap , LXX ; En 6:6 [Syncellus]; TestAbr A 2 p. 78, 19 [Stone p. 4]; 11 p. 89, 23 [Stone p. 26]; JosAs 2:1; 4:14; Joseph .) marcador</p><p class=\"entry-text\">① de extensão ou grau: como, na medida em que <span class=\"greek\">καθότι</span> <span class=\"greek\">ἄν</span> ( Michel 534, 28 [III b.c. ] <span class=\"greek\">καθότι</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">δοκεῖ</span> <span class=\"greek\">αὐτοῖς</span> ; Lev 25:16 ; 27:12 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.45\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:45</a> ; 4:35.</p><p class=\"entry-text\">② de justificativa de alguma coisa: porque, visto que ( Polyb . 18, 21, 6; Jos. , Ant. 18, 90 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:7</a> ; 19:9 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:24</a> ; 17:31 ; ITr 5:2 ; GJs 1:2; 2:2 e 3.</p><p class=\"entry-text\">③ de juramento: (juro) que, como <span class=\"greek\">ὅτι</span> ( e.g. 1 Km 26:16 ) <span class=\"greek\">ζῇ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> <span class=\"greek\">μου</span> <span class=\"greek\">κ</span>. <span class=\"greek\">οὐ</span> <span class=\"greek\">γινώσκω</span> … tão certo como vive meu Deus, não sei … GJs 13:3; 15:3f.</p><p class=\"entry-text\">④ de discurso direto: nesse particular (aproximação, mas convém deixá-lo sem tradução) <span class=\"greek\">λέγουσα</span> <span class=\"greek\">κ</span> . 13:3.— M-M .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0182-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθώς</h1><div class=\"entry-meta\"><span>advérbio; conjunção</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">advérbio (seu uso foi vigorosamente rejeitado por Frínico, p. 425 Lob. ; Aristot .+; ins , pap , LXX , pseudepigr. , Philo ; Jos. , Ant. 12, 158 al. ; Ar. ; Just ., A I, 51, 6; Tat . 33, 3) marcador</p><p class=\"entry-text\">① de comparação: assim como; seguido de <span class=\"greek\">οὕτως</span>, assim como … também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:30</a> ; 17:26 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:14</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:5</a> ; 10:7 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:13</a> ; 1J 2:6 ; 1 Cl 20:6 ; Hs 9, 4, 1 . <span class=\"greek\">κ</span>. … <span class=\"greek\">ὁμοίως</span> assim como … assim também, igualmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:31</a>. <span class=\"greek\">κ</span>. … <span class=\"greek\">ταῦτα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:28</a> ; <span class=\"greek\">τὰ</span> <span class=\"greek\">αὐτὰ</span> … <span class=\"greek\">κ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:14</a>. <span class=\"greek\">κ</span>. … <span class=\"greek\">καί</span> assim como … assim também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:9</a> ; 17:18 ; 20:21 ; 1J 2:18 ; 4:17 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.49\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:49</a>. <span class=\"greek\">οὕτως</span> <span class=\"greek\">καθώς</span> assim como <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:24</a>. Frequentemente se omite o demonstrativo: <span class=\"greek\">ποιήσαντες</span> <span class=\"greek\">κ</span>. <span class=\"greek\">συνέταξεν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἰησοῦς</span> fizeram conforme Jesus lhes ordenara <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:6</a> ; cf. 28:6 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:7</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:2</a>, 55, 70 ; 11:1 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:23</a> ; 5:23 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:8</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:13</a> ; 15:7 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:2</a> ; 10:6 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:14</a> ; 9:3 ; 11:12 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:17</a> ; Hm 12, 2, 5 ; 1 Cl 16:2 . Como fórmula <span class=\"greek\">κ</span>. <span class=\"greek\">γέγραπται</span> como está escrito ( cf. Sb 7532, 16 [74 b.c. ] <span class=\"greek\">καθὰ</span> <span class=\"greek\">γέγραπται</span> ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:24</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:2</a> ; 9:13 ; 14:21 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:23</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:15</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:17</a> ; 2:24 ; 3:4, 10 ; 4:17 ; 8:36 e muito frequentemente em Paulo. Ver o verbete <span class=\"greek\">καθάπερ</span> e cf. <span class=\"greek\">κ</span>. <span class=\"greek\">προείρηκεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:29</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">διδάσκω</span> como ensino <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:17</a>. <span class=\"greek\">καθὼς</span> <span class=\"greek\">εἶπον</span> <span class=\"greek\">ὑμῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:26</a> variante de leitura <span class=\"greek\">καθὼς</span> <span class=\"greek\">εἶπεν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">γραφή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:38</a>. Às vezes é preciso suprir pelo contexto a oração correlativa: <span class=\"greek\">κ</span>. <span class=\"greek\">παρεκάλεσά</span> <span class=\"greek\">σε</span> ( POxy 1299, 9 <span class=\"greek\">καθὼς</span> <span class=\"greek\">ἐνετειλάμην</span> <span class=\"greek\">σοι</span>= [age, faze] como te instruí) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:3</a> ; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:6</a>. <span class=\"greek\">ἤρξατο</span> <span class=\"greek\">αἰτεῖσθαι</span> (<span class=\"greek\">ἵνα</span> <span class=\"greek\">ποιήσῃ</span> <span class=\"greek\">αὐτοῖς</span>) <span class=\"greek\">κ</span>. <span class=\"greek\">ἐποίει</span> <span class=\"greek\">αὐτοῖς</span> como costumava fazer por eles <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:8</a>. <span class=\"greek\">ἰάθη</span> <span class=\"greek\">Σαλώμη</span> <span class=\"greek\">καθὼς</span> <span class=\"greek\">προσεκύνησεν</span> Salomé foi curada em conformidade com sua oração GJs 20:3. Em combinação com <span class=\"greek\">εἶναι</span> : <span class=\"greek\">ὀψόμεθα</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐστιν</span> vê-lo-emos assim como ele é 1J 3:2, no sentido de <span class=\"greek\">ποῖος</span>, «como» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.58\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:58</a> ; 14:27 (ver HLjungvik, Eranos 62, ’64, 34f). <span class=\"greek\">κ</span>. <span class=\"greek\">ἀληθῶς</span> <span class=\"greek\">ἐστιν</span> como realmente é <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:13</a>. Às vezes a expressão é tão condensada que compara opostos <span class=\"greek\">ἀγαπῶμεν</span> <span class=\"greek\">ἀλλήλους</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">Κάϊν</span> 1J 3:11f. <span class=\"greek\">οὗτός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄρτος</span> … <span class=\"greek\">οὐ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἔφαγον</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">πατέρες</span> bem diferente do que os pais comeram <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.58\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:58</a>. Em expressão condensada, para introduzir uma citação, por exemplo <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κατάπαυσιν</span> … , <span class=\"greek\">κ</span>. <span class=\"greek\">εἴρηκεν</span> (conforme Ps 94:11 ) no descanso … acerca do qual Deus disse <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:3</a> ; 8:5 (ver HLjungvik, Eranos 62, ’64, 36f).</p><p class=\"entry-text\">② de extensão ou grau: conforme, na medida em que ( Num 26:54 ; Ar. 2, 1; 4, 1) <span class=\"greek\">κ</span>. <span class=\"greek\">ἠδύναντο</span> <span class=\"greek\">ἀκούειν</span> até onde eram capazes de compreender <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:33</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">εὐπορεῖτό</span> <span class=\"greek\">τις</span> cada um segundo suas possibilidades (financeiras) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:29</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">βούλεται</span> conforme o Espírito quer ( NRSV ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:11</a> ; cf. versículo 18. <span class=\"greek\">κ</span>. <span class=\"greek\">ἔλαβεν</span> <span class=\"greek\">χάρισμα</span> na medida em que recebeu um dom <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:10</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:4</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.38\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:38</a>.</p><p class=\"entry-text\">③ de causa: visto que, já que, especialmente como conjunção inicial da oração ( B-D-F § 453, 2 ; Rob. 968 ; 1382 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:2</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:28</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:6</a> ; 5:7 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:4</a> ; 4:32 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:7</a>.</p><p class=\"entry-text\">④ de tempo: quando, enquanto. O sentido temporal de <span class=\"greek\">κ</span> . é controvertido, mas parece bem estabelecido ( 2 Macc 1:31 ; 2 Esdr 15 :6; EpArist 310 ; s. <span class=\"greek\">ὡς</span> 8); <span class=\"greek\">κ</span> . ( variante de leitura <span class=\"greek\">ὡς</span> ) <span class=\"greek\">ἤγγιζεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">χρόνος</span> quando o tempo se aproximava <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:17</a> ( EpArist 236 <span class=\"greek\">καθὼς</span> <span class=\"greek\">εὔκαιρον</span> <span class=\"greek\">ἐγένετο</span> ).</p><p class=\"entry-text\">⑤ Após verbos declarativos, introduz discurso indireto (= <span class=\"greek\">ὡς</span>, <span class=\"greek\">πῶς</span>) <span class=\"greek\">Συμεὼν</span> <span class=\"greek\">ἐξηγήσατο</span>, <span class=\"greek\">κ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἐπεσκέψατο</span> S. relatou como Deus visitou <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:14</a>. <span class=\"greek\">μαρτυρούντων</span> <span class=\"greek\">σου</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀληθείᾳ</span>, <span class=\"greek\">κ</span>. <span class=\"greek\">σὺ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀληθείᾳ</span> <span class=\"greek\">περιπατεῖς</span> que testemunham da tua verdade, isto é, de como andas na verdade 3J 3. — M-M .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0182-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθώσπερ</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">advérbio = <span class=\"greek\">καθώς</span> (uma expressão redundante como <span class=\"greek\">οἷον</span> <span class=\"greek\">ὡς</span>, <span class=\"greek\">οἷον</span> <span class=\"greek\">ὥσπερ</span> ; Himerius , Or. 1, 20; Paroem. Gr. II p. 73, 11; 473, 13; Nicetas Eugen . 8, 106 H. ) assim como <span class=\"greek\">κ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">Ἀαρών</span> assim como também Arão (foi) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:4</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:18</a> variante de leitura (em lugar de <span class=\"greek\">καθάπερ</span> ).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0182-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καί</h1><div class=\"entry-meta\"><span>conjunção; advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">conjunção ( Hom .+), de longe, a partícula grega mais frequente no Novo Testamento ; visto que é usada não apenas muito mais frequentemente aqui do que em outros textos gregos, mas também, muitas vezes, com sentido diverso, ou melhor, em circunstâncias diferentes, contribui significativamente para a coloração peculiar do estilo neotestamentário.—HMcArthur, <span class=\"greek\">ΚΑΙ</span> Frequency in Greek Letters, NTS 15, ’68/69, 339–49. A vivaz versatilidade de <span class=\"greek\">κ</span> . (para o grego anterior, ver Denniston 289–327) pode facilmente perder o vigor na tradução «e», cuja repetição em curto espaço de texto não dispõe do apoio de certas características expressivas da sintaxe grega.</p><p class=\"entry-text\">① marcador de ligação: e</p><p class=\"entry-text\">ⓐ palavras isoladas <span class=\"greek\">α</span>. em geral <span class=\"greek\">Ἰάκωβος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Ἰωσὴφ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Σίμων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Ἰούδας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:55</a>. <span class=\"greek\">χρυσὸν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λίβανον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σμύρναν</span> 2:11. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐντολὴ</span> <span class=\"greek\">ἁγία</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δικαία</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀγαθή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:12</a>. <span class=\"greek\">πολυμερῶς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πολυτρόπως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:1</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πατήρ</span> Deus, que também é Pai <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:24</a> ; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:3</a> ; 11:31 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:3</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:27</a> ; 3:9 al. —Liga duas ocorrências da mesma palavra para dar ênfase ( OGI 90, 19 [196 b.c. ] <span class=\"greek\">Ἑρμῆς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">μέγας</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μέγας</span> ; papiro em Mayser II/1, 54) <span class=\"greek\">μείζων</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μείζων</span> cada vez maior Hv 4, 1, 6 . <span class=\"greek\">ἔτι</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἔτι</span> repetidas vezes B 21:4 ; Hs 2, 6 ( B-D-F § 493, 1 ; 2 ; ver Rob. 1200 ). <span class=\"greek\">β</span>. com numerais, vindo o número maior em primeiro lugar <span class=\"greek\">δέκα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁκτώ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:16</a>. <span class=\"greek\">τεσσεράκοντα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἕξ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:20</a>. <span class=\"greek\">τετρακόσιοι</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πεντήκοντα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:20</a>. —O <span class=\"greek\">καί</span> de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:1</a> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">στόματος</span> <span class=\"greek\">δύο</span> <span class=\"greek\">μαρτύρων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τριῶν</span> <span class=\"greek\">σταθήσεται</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">ῥῆμα</span> = «ou» ([ variante de leitura <span class=\"greek\">ἢ</span> <span class=\"greek\">τριῶν</span> em lugar de <span class=\"greek\">καὶ</span> <span class=\"greek\">τριῶν</span>, como se lê em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:16</a> ]; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:13</a> variante de leitura <span class=\"greek\">σήμερον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">αὔριον</span> = «hoje ou amanhã», mas ver, sobretudo, Tucídides 1, 82, 2; Pla ., Phd. 63e; X. , De Re Equ. 4, 4 <span class=\"greek\">ἁμάξας</span> <span class=\"greek\">τέτταρας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πέντε</span> ; Heraclides, Pol . 58 <span class=\"greek\">τρεῖς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τέσσαρας</span> ; Polyb . 3, 51, 12 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">δυεῖν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τρισὶν</span> <span class=\"greek\">ἡμέραις</span> ; 5, 90, 6; Diod S 34 + 35 Fgm. 2, 28 <span class=\"greek\">εἷς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δύο</span> =um ou dois; escólio a Apolônio de Rodes 4, 1091 p. 305, 22 W. <span class=\"greek\">τριέτης</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τετραέτης</span> ) toda acusação deve ser confirmada pelo depoimento de duas ou três testemunhas, conforme a explicação de Dt 19:15. <span class=\"greek\">γ</span>. acrescentando o todo à parte: e em geral ( Aristoph ., Nub. 1239 <span class=\"greek\">τὸν</span> <span class=\"greek\">Δία</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">θεούς</span> ; Thu . 1, 116, 3; 7, 65, 1) <span class=\"greek\">Πέτρος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀπόστολοι</span> Pedro e os demais apóstolos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:29</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀρχιερεῖς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">συνέδριον</span> <span class=\"greek\">ὅλον</span> o sumo sacerdote e todos os demais membros do conselho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.59\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:59</a>. Inversamente, acrescentando ao todo uma parte especialmente importante: e especialmente ( <span class=\"greek\">πᾶς</span> <span class=\"greek\">Ἰουδὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Ἰερουσαλήμ</span> 2 Ch 35:24 ; cf. 32, 33 ; 1 Macc 2:6 ) <span class=\"greek\">τοῖς</span> <span class=\"greek\">μαθηταῖς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">Πέτρῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:7</a>. <span class=\"greek\">σὺν</span> <span class=\"greek\">γυναιξὶ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">Μαριάμ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:14</a>. <span class=\"greek\">δ</span>. As expressões ligadas por <span class=\"greek\">καί</span> podem formar uma hendíade ( Alcaeus 117, 9f D . 2 <span class=\"greek\">χρόνος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">καρπός</span> =tempo da frutificação; Soph ., Aj. 144; 749; Polyb . 6, 9, 4; 6, 57, 5 <span class=\"greek\">ὑπεροχὴ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δυναστεία</span> =1, 2, 7; 5, 45, 1 <span class=\"greek\">ὑπεροχὴ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δυναστείας</span> ; Diod S 5, 67, 3 <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἀνανέωσιν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μνήμην</span> =renovação da lembrança; 15, 63, 2 <span class=\"greek\">ἀνάγκη</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τύχη</span> =imposição do destino; 16, 93, 2 <span class=\"greek\">ἐπιβουλὴ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">θάνατος</span> =uma conspiração mortal; Jos. , Ant. 12, 98 <span class=\"greek\">μετὰ</span> <span class=\"greek\">χαρᾶς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">βοῆς</span> =com um grito de alegria; 17, 82 <span class=\"greek\">ἀκρίβεια</span> <span class=\"greek\">κ</span>. <span class=\"greek\">φυλακή</span> ) <span class=\"greek\">ἐξίσταντο</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">συνέσει</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἀποκρίσεσιν</span> <span class=\"greek\">αὐτοῦ</span> maravilharam-se com suas respostas inteligentes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:47</a>. <span class=\"greek\">δώσω</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">στόμα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">σοφίαν</span> eu vos darei palavras sábias 21:15. <span class=\"greek\">τροφὴ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">εὐφροσύνη</span> alegria em relação ao (vosso) alimento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:17</a>. <span class=\"greek\">ἐλπὶς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἀνάστασις</span> esperança da ressurreição 23:6 ( 2 Macc 3:29 <span class=\"greek\">ἐλπὶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σωτηρία</span> ; ver OLagercrantz, ZNW 31, ’32, 86f; GBjörck, ConNeot 4, ’40, 1–4). <span class=\"greek\">ε</span>. Uma característica coloquial é a coordenação de dois verbos, um dos quais corresponderia a um particípio (ver B-D-F § 471 ; Rob. 1135 f) <span class=\"greek\">ἀποτολμᾷ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">λέγει</span> = <span class=\"greek\">ἀποτολμῶν</span> <span class=\"greek\">λέγει</span> ele se atreve a dizer <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:20</a>. <span class=\"greek\">ἔσκαψεν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐβάθυνεν</span> (= <span class=\"greek\">βαθύνας</span> ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:48</a>. <span class=\"greek\">ἐκρύβη</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐξῆλθεν</span> (= <span class=\"greek\">ἐξελθών</span> ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.59\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:59</a>. Semelhantemente, <span class=\"greek\">χαίρων</span> <span class=\"greek\">κ</span>. <span class=\"greek\">βλέπων</span> alegro-me por ver <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:5</a>. Ligação de oração subordinada e particípio <span class=\"greek\">Μαριὰμ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἦλθεν</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">ἰδοῦσα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:32</a> variante de leitura Cf. <span class=\"greek\">παραλαβών</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀνέβη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:28</a> variante de leitura</p><p class=\"entry-text\">ⓑ orações e períodos <span class=\"greek\">α</span>. em geral : <span class=\"greek\">ἐν</span> <span class=\"greek\">γαστρὶ</span> <span class=\"greek\">ἕξει</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τέξεται</span> <span class=\"greek\">υἱόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:23</a> ( Is 7:14 ). <span class=\"greek\">εἰσῆλθον</span> … <span class=\"greek\">κ</span>. <span class=\"greek\">ἐδίδασκον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:21</a>. <span class=\"greek\">διακαθαριεῖ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἅλωνα</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">συνάξει</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">σῖτον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:12</a>. <span class=\"greek\">κεκένωται</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πίστις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κατήργηται</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπαγγελία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:14</a> e muito frequentemente Ligando duas perguntas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:23</a>, ou citações ( por exemplo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:20</a> ), e diálogos ( <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:8</a> ), ou possibilidades alternativas ( 13:18 ). <span class=\"greek\">β</span>. Outra característica frequente, oriunda do hebraico ou da linguagem cotidiana, é empregar <span class=\"greek\">κ</span> . como conectivo onde um uso mais diferenciado recorreria a outras partículas: <span class=\"greek\">καὶ</span> <span class=\"greek\">εἶδον</span> <span class=\"greek\">καὶ</span> (em lugar de <span class=\"greek\">ὅτι</span> ) <span class=\"greek\">σεισμὸς</span> <span class=\"greek\">ἐγένετο</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:12</a>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ἤκουσεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">βασιλεὺς</span> … <span class=\"greek\">καὶ</span> (em lugar de <span class=\"greek\">ὅτι</span> ) <span class=\"greek\">ἔλεγον</span> e o rei soube que diziam <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:14</a> (ver HLjungvik, ZNW 33, ’34, 90–92; sobre isso, ver JBlinzler, Philol . 96, ’43/44, 119–31). <span class=\"greek\">τέξεται</span> <span class=\"greek\">υἱὸν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">καλέσεις</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">αὐτοῦ</span> (em lugar de <span class=\"greek\">οὗ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">καλ</span> .) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:21</a> ; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:6</a> ; 11:44. <span class=\"greek\">καλόν</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">ὧδε</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ποιήσωμεν</span> <span class=\"greek\">σκηνάς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:5</a>. Especialmente frequente é a fórmula da narrativa histórica <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐγένετο</span> … <span class=\"greek\">καὶ</span> (à maneira de וַ … וַיְהִי ) e aconteceu … que <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:10</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:15</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:1</a> variante de leitura (em lugar de <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">δὲ</span> … <span class=\"greek\">καὶ</span> ; assim também o texto de 6:12 ), 12, 17 ; 14:1 ; 17:11 al. ( Gen 7:10 al. ; JosAs 11:1; 22:1). Ver MJohannessohn, Das bibl. <span class=\"greek\">Καὶ</span> <span class=\"greek\">ἐγένετο</span> u. seine Geschichte, 1926 (extraído de ZVS 35, 1925, 161–212); KBeyer, Semitische Syntax im NT I, 1 ’62, 29–62; Mlt-Turner 334f; ÉDelebecque, Études Grecques sur L’Évangile de Luc ’76, 123–65; JVoelz, The Language of the NT : ANRW II/25/2, 893–977, especialmente 959–64.—Como na linguagem popular, <span class=\"greek\">κ</span> . é empregado em sucessão rápida <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:9ff</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:12ff</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:32ff</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:13ff</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:5f</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:12ff</a> ; 9:1ff. Sobre esse tipo de expressão coloquial, que coordena orações independentes em vez de subordinar uma à outra (parataxe em vez de hipotaxe) ver B-D-F § 458 ; Rdm. 2 p. 222; Rob. 426 ; Dssm. , LO 105ff ( LAE 129 ff), com numerosas referências e paralelos de fontes não cristãs. Esse recurso é particularmente frequente, por exemplo, em Polieno 2, 3, 2–4; 2, 4, 3; 3, 9, 10; 3, 10, 2; 4, 6, 1; 7, 36 al. <span class=\"greek\">γ</span>. Também há coordenação, e não subordinação, quando <span class=\"greek\">κ</span> . liga uma expressão temporal àquilo que ocorre naquele momento ( Od . 5, 362; Hdt. 7, 217; Thu . 1, 50, 5; Pla ., Symp. 220c; Aeschin . 3, 71 <span class=\"greek\">νὺξ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">μέσῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παρῆμεν</span> ; ver B-D-F § 442, 4 ; KBrugmann 4 -AThumb, Griechische Gramm. 1913, 640*): <span class=\"greek\">ἤγγικεν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ὥρα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">παραδίδοται</span> chegou a hora em que ele será entregue <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:45</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ἐσταύρωσαν</span> <span class=\"greek\">αὐτόν</span> quando o crucificaram <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:25</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ἀνέβη</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἰεροσόλυμα</span> quando subiu a Jerusalém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:13</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">συντελέσω</span> quando estabelecerei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:8</a> ( Jer 38:31 ); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:35</a> ; 7:33 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:43</a> ; 23:44 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:7</a>. <span class=\"greek\">δ</span>. A introdução de uma apódose por <span class=\"greek\">καί</span> deve-se propriamente à influência hebraica e da LXX ( B-D-F § 442, 7 ; Abel §78a, 6 p. 341; Mlt-H. 422; KBeyer, Semitische Syntax im NT I, 1 ’62, 66–72; mas não soa ofensiva a ouvidos habituados ao bom grego : ver Il. 1, 478; Hdt. 1, 79, 2; de modo semelhante, Thu . 2, 93, 4 <span class=\"greek\">ὡς</span> <span class=\"greek\">ἔδοξεν</span> <span class=\"greek\">αὐτοῖς</span>, <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐχώρουν</span> <span class=\"greek\">εὐθύς</span> ; 8, 27, 5; Herm. Wr. 13, 1 … , <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔφης</span> ; Delebecque [ver acima em <span class=\"greek\">β</span>] 130–32) <span class=\"greek\">καὶ</span> <span class=\"greek\">ὅτε</span> <span class=\"greek\">ἐπλήσθησαν</span> <span class=\"greek\">ἡμέραι</span> <span class=\"greek\">ὀκτὼ</span> … , <span class=\"greek\">κ</span>. <span class=\"greek\">ἐκλήθη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:21</a> ; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:20</a>. Também <span class=\"greek\">κ</span>. <span class=\"greek\">ἰδού</span> numa apódose <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:12</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:10</a>. <span class=\"greek\">ε</span>. ligando orações negativas e afirmativas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:14</a>. <span class=\"greek\">οὔτε</span> <span class=\"greek\">ἄντλημα</span> <span class=\"greek\">ἔχεις</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">φρέαρ</span> <span class=\"greek\">ἐστὶ</span> <span class=\"greek\">βαθύ</span> não tens balde, e o poço é fundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:11</a> ; cf. 3J 10 ( <span class=\"greek\">οὔτε</span> … <span class=\"greek\">καί</span> Eur ., Iph. Taur. 591f; Longus , Past. 1, 17; 4, 28; Aelian , NA 1, 57; 11, 9; Lucian , Dial. Meretr. 2, 4 <span class=\"greek\">οὔτε</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">Λεσβία</span>, <span class=\"greek\">Δωρί</span>, <span class=\"greek\">πρὸς</span> <span class=\"greek\">σὲ</span> <span class=\"greek\">ἐψεύσατο</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σὺ</span> <span class=\"greek\">τἀληθῆ</span> <span class=\"greek\">ἀπήγγελκας</span> <span class=\"greek\">Μυρτίῳ</span> ‘Nem tudo o que Lésbia te disse, Dóris, era mentira; e certamente relataste a verdade a Mírtio’). Após uma oração negativa, que influencia a oração iniciada por <span class=\"greek\">καί</span> : <span class=\"greek\">μήποτε</span> <span class=\"greek\">καταπατήσουσιν</span> … <span class=\"greek\">κ</span>. <span class=\"greek\">στραφέντες</span> <span class=\"greek\">ῥήξωσιν</span> <span class=\"greek\">ὑμᾶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:6</a> ; cf. 5:25 ; 10:38 ; 13:15 ( Is 6:10 ); 27:64 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.58\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:58</a> ; 21:34 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.53\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:53</a> ; 12:40 ( Is 6:10 ); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:27</a> ( Is 6:10 ); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:5</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:15</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:15</a>. <span class=\"greek\">ζ</span>. para introduzir resultado decorrente do anterior: e então, e assim <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:15</a> ; 23:32 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:34</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:9</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:19</a> ; 1J 3:19. <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔχομεν</span> e assim temos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:19</a>. Especialmente após o imperativo ou expressão de natureza imperativa ( Soph ., Oed. Col. 1410ff <span class=\"greek\">θέσθε</span> … <span class=\"greek\">καὶ</span> … <span class=\"greek\">οἴσει</span> , El. 1207; Sir 2:6 ; 3:17 ) <span class=\"greek\">δεῦτε</span> <span class=\"greek\">ὀπίσω</span> <span class=\"greek\">μου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ποιήσω</span> e então farei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:19</a>. <span class=\"greek\">εἰπὲ</span> <span class=\"greek\">λόγῳ</span>, <span class=\"greek\">κ</span>. <span class=\"greek\">ἰαθήσεται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">παῖς</span> <span class=\"greek\">μου</span> dize uma palavra, e então meu servo será curado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:8</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:7</a> ; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:7</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:22</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:28</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:16</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:7</a>, 10 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:1</a>. — <span class=\"greek\">καί</span> introduz uma oração breve que confirma a existência de algo que assim deveria ser: <span class=\"greek\">ἵνα</span> <span class=\"greek\">τέκνα</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">κληθῶμεν</span>, <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐσμέν</span> que fôssemos chamados filhos de Deus; e de fato o somos ( <span class=\"greek\">καλέω</span> 1d) 1J 3:1 ( Appian , Bell. Civ. 2, 40 §161 deveriam conquistar a Sardenha, <span class=\"greek\">καὶ</span> <span class=\"greek\">κατέλαβον</span> =e de fato a tomaram; 4, 127 §531 um dia decidiria [ <span class=\"greek\">κρίνειν</span> ] o destino de Roma, <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐκρίθη</span> ). <span class=\"greek\">η</span>. dando ênfase a um fato surpreendente, inesperado ou digno de nota: e contudo, e apesar disso, não obstante ( Eur ., Herc. Fur. 509; Philostrat ., Her . 11 [II 184, 29 Kayser] <span class=\"greek\">ῥητορικώτατον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δεινόν</span> ; Longus , Past. 4, 17 <span class=\"greek\">βουκόλος</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">Ἀγχίσης</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔσχεν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">Ἀφροδίτη</span> ) <span class=\"greek\">κ</span>. <span class=\"greek\">σὺ</span> <span class=\"greek\">ἔρχῃ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">μέ</span>; e contudo vens a mim? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:14</a> ; cf. 6:26 ; 10:29 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:12</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:5</a>, 10 ; 3:11, 32 ; 5:40 ; 6:70 ; 7:28 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:2</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:9</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:9</a> ( Ps 94:9 ); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:1</a>. Também para ligar algo inesperado ou notável a uma tentativa de alguma espécie (JBlomqvist, Das sogennante <span class=\"greek\">και</span> adversativum ’79); mas <span class=\"greek\">ζητεῖ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">οὐχ</span> <span class=\"greek\">εὑρίσκει</span> mas não encontra nenhum (lugar de descanso) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:43</a>. <span class=\"greek\">ἐπεθύμησαν</span> <span class=\"greek\">ἰδεῖν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">οὐχ</span> <span class=\"greek\">εἶδαν</span> mas não o viram 13:17 ; cf. 26:60 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:7</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:18</a>. Cf. GJs 18:3 (não consta do papiro). Talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:20</a>. Introduzindo uma resposta contrastante <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀποδώσεις</span> <span class=\"greek\">μοι</span> Hv 2, 1, 3 . <span class=\"greek\">θ</span>. para introduzir uma pergunta abrupta, frequentemente expressando surpresa, hostilidade, incredulidade etc. ( B-D-F § 442, 8 . Sobre exemplos desse emprego na literatura antiga, ver Kühner-G. II p. 247f; para períodos posteriores, EColwell, The Gk. of the Fourth Gospel ’31, 87f): <span class=\"greek\">κ</span>. <span class=\"greek\">πόθεν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">τοῦτο</span>; como mereci isto? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:43</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">τίς</span>; quem, então? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:26</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:29</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:36</a>. <span class=\"greek\">καὶ</span> <span class=\"greek\">τί</span> <span class=\"greek\">γέγονεν</span> <span class=\"greek\">ὅτι</span> … ; como acontece que … ? 14:22. <span class=\"greek\">καὶ</span> <span class=\"greek\">πῶς</span> <span class=\"greek\">σὺ</span> <span class=\"greek\">λέγεις</span> … ; como é, então, que dizes … <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:9</a> variante de leitura Com uma prótase <span class=\"greek\">εἰ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">λυπῶ</span> <span class=\"greek\">ὑμᾶς</span>, <span class=\"greek\">κ</span>. <span class=\"greek\">τίς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">εὐφραίνων</span> <span class=\"greek\">με</span>; pois, se vos entristeço, quem então me alegrará? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:2</a> ( cf. Ps. -Clem., Hom . 2, 43; 44 <span class=\"greek\">εἰ</span> [<span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span>] <span class=\"greek\">ψεύδεται</span>, <span class=\"greek\">καὶ</span> <span class=\"greek\">τίς</span> <span class=\"greek\">ἀληθεύει</span>; ). Assim, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:22</a> provavelmente deve ser pontuado da seguinte maneira (ver ADebrunner, GGA 1926, 151): <span class=\"greek\">εἰ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ζῆν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκί</span>, <span class=\"greek\">τοῦτο</span> <span class=\"greek\">μοι</span> <span class=\"greek\">καρπὸς</span> <span class=\"greek\">ἔργου</span>, <span class=\"greek\">καὶ</span> <span class=\"greek\">τί</span> <span class=\"greek\">αἱρήσομαι</span>; <span class=\"greek\">οὐ</span> <span class=\"greek\">γνωρίζω</span> mas, se viver aqui significa continuar um trabalho frutífero, então que escolherei? Realmente não sei. <span class=\"greek\">καὶ</span> <span class=\"greek\">πῶς</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">υἱός</span> <span class=\"greek\">ἐστιν</span>; como, então, é ele seu filho? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:44</a> ( cf. Gen 39:9 ). <span class=\"greek\">ι</span>. para introduzir um parêntese ( Eur ., Orest. 4, Hel. 393; X. , Equ. 11, 2.— B-D-F § 465, 1 ; Rob. 1182 ) <span class=\"greek\">κ</span>. <span class=\"greek\">ἐκωλύθην</span> <span class=\"greek\">ἄρχι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">δεῦρο</span> mas até aqui fui impedido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:13</a>.</p><p class=\"entry-text\">ⓒ frequentemente explicativo, isto é, uma palavra ou oração é ligada por <span class=\"greek\">καί</span> a outra para explicar o que a precede: e assim, isto é, a saber ( PPetr II, 18 [1], 9 <span class=\"greek\">πληγὰς</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">πλείους</span> =golpes … na verdade, muitos deles.—Kühner-G. II 247; B-D-F § 442, 9 ; Rob. 1181 ; Mlt-Turner 335) <span class=\"greek\">χάριν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἀποστολήν</span> graça, isto é, o ofício de apóstolo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:5</a>. <span class=\"greek\">ἀπήγγειλαν</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">δαιμονιζομένων</span> relataram tudo, a saber, o que acontecera aos possessos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:33</a>. <span class=\"greek\">καὶ</span> <span class=\"greek\">χάριν</span> <span class=\"greek\">ἀντὶ</span> <span class=\"greek\">χάριτος</span> isto é, graça sobre graça <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:16</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:5</a> ; 15:38 .— <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:5</a>. —Outros empregos explicativos são <span class=\"greek\">καὶ</span> <span class=\"greek\">οὗτος</span>, <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῦτο</span>, <span class=\"greek\">καὶ</span> <span class=\"greek\">ταῦτα</span> (o primeiro e o último já ocorrem no grego antigo : Hdt. , X. et al. ; ver Kühner-G. I 647; II 247) e, também com valor intensificador: e de fato, e ainda por cima <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χρ</span>., <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῦτον</span> <span class=\"greek\">ἐσταυρωμένον</span> Jesus Cristo, e precisamente ele crucificado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:2</a>. <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῦτο</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:11</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:6</a>, 8 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:8</a>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ταῦτα</span> com particípio: e certamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:12</a>. See B-D-F § 290, 5 ; 425, 1 ; 442, 9 .—O valor intensificador de <span class=\"greek\">καί</span> também é evidente em <span class=\"greek\">Ῥωμαῖον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀκατάκριτον</span> cidadão romano, e ainda por cima sem condenação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:25</a>. <span class=\"greek\">ἔρχεται</span> <span class=\"greek\">ὥρα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">ἐστιν</span> vem a hora; na verdade, ela já chegou <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:25</a>. <span class=\"greek\">προσέθηκεν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κατέκλεισεν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰωάννην</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">φυλακῇ</span> acrescentou isso a tudo o mais, isto é, prender João <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:20</a>.</p><p class=\"entry-text\">ⓓ Após <span class=\"greek\">πολύς</span> e antes de um segundo adjetivo, <span class=\"greek\">καί</span> é pleonástico do ponto de vista das línguas modernas (grego antigo: Homero e outros [Kühner-G. II 252, 1]; cf. Cebes 1, 1 <span class=\"greek\">πολλὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἄλλα</span> <span class=\"greek\">ἀναθήματα</span> ; 2, 3; B-D-F § 442, 11 ) <span class=\"greek\">πολλὰ</span> … <span class=\"greek\">κ</span>. <span class=\"greek\">ἄλλα</span> <span class=\"greek\">σημεῖα</span> muitos outros sinais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:30</a> ( cf. Jos. , Ant. 3, 318 ). <span class=\"greek\">πολλὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">βαρέα</span> <span class=\"greek\">αἰτιώματα</span> muitas acusações graves <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:7</a>. <span class=\"greek\">πολλὰ</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">ἕτερα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:18</a> ( cf. Himerius , Or. 40 [=Or. 6], 6 <span class=\"greek\">πολλὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἄλλα</span> ). <span class=\"greek\">πολλοὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀνυπότακτοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:10</a>.</p><p class=\"entry-text\">ⓔ introduzindo um novo assunto, com ligação pouco estreita: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:23</a> ; 8:14, 23, 28 ; 9:1, 9, 27, 35 ; 10:1 ; 12:27 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:1</a>, 21 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:26</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:19</a> e frequentemente</p><p class=\"entry-text\">ⓕ <span class=\"greek\">καί</span> … <span class=\"greek\">καί</span>: tanto … como, não apenas … mas também ( Synes ., Dreams 10 p. 141b <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀπιστεῖν</span> <span class=\"greek\">ἔξεστι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πιστεύειν</span> .— B-D-F § 444, 3 ; Rob. 1182 ; Mlt-Turner 335) ligando expressões isoladas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:28</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:41</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:33</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:13</a> ; 4:12. <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀλίγῳ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">μεγάλῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:29</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ἅπαξ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">δίς</span> (ver <span class=\"greek\">ἅπαξ</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:16</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:18</a>. Ligando orações ou períodos inteiros: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:13</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:28</a> ; 9:37 ; 12:28 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:22</a>. Introduzindo contrastes: embora … contudo (Anthol. VII, 676 <span class=\"greek\">Δοῦλος</span> <span class=\"greek\">Ἐπίκτητος</span> <span class=\"greek\">γενόμην</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σῶμ</span>’ <span class=\"greek\">ἀνάπηρος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πενίην</span> <span class=\"greek\">῏Ιρος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φίλος</span> <span class=\"greek\">ἀθανάτοις</span> ‘Eu fui Epicteto, escravo, aleijado no corpo e, na pobreza, um Iro [mendigo em Homero, Odisseia], mas caro aos imortais’) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:24</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:3</a>. <span class=\"greek\">καὶ</span> … <span class=\"greek\">κ</span>. <span class=\"greek\">οὐ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:36</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:36</a>. <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐ</span> … <span class=\"greek\">καί</span> 17:25 ; <span class=\"greek\">κ</span>. … <span class=\"greek\">κ</span> . ora … ora <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:22</a>. Sobre <span class=\"greek\">τὲ</span> … <span class=\"greek\">καί</span>, ver <span class=\"greek\">τέ</span> 2c. Às vezes, com <span class=\"greek\">ἤ</span> (ver o verbete) 1a <span class=\"greek\">β</span> .—HCadbury, Superfluous <span class=\"greek\">καί</span> in the Lord’s Prayer ( i.e. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:12</a>) and Elsewhere: Munera Studiosa (=WHatch Festschr. ) ’46.</p><p class=\"entry-text\">② marcador de relação aditiva não coordenativa para ligar orações e períodos: também, igualmente, funcionando como advérbio</p><p class=\"entry-text\">ⓐ simplesmente <span class=\"greek\">κ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἄλλην</span> também a outra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:39</a> ; cf. vs. 40 ; 6:21 ; 12:45 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:38</a> ; 2:26 ; 8:7 e frequentemente Empregado frequentemente com pronomes <span class=\"greek\">κἀγώ</span> ( q.v. ). <span class=\"greek\">καὶ</span> <span class=\"greek\">σύ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.73\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:73</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ὑμεῖς</span> 20:4, 7 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:31</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.47\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:47</a> e frequentemente <span class=\"greek\">κ</span>. <span class=\"greek\">αὐτός</span> (ver <span class=\"greek\">αὐτός</span> 1f).</p><p class=\"entry-text\">ⓑ intensivo: até, mesmo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:46f</a> ; 10:30 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:27</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:17</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:9</a> variante de leitura ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:39</a> ; 22:28 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:24</a> ( <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">καί</span> ); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:10</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:8</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:17</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:12</a> ; Phlm 21 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:25</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:19</a> (mas ver a subdivisão d abaixo); Jd 23 ; Hs 5, 2, 10 ; 7:1 ; <span class=\"greek\">ἔτι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">νῦν</span> Dg 2:3 . CBlackman, JBL 87, ’68, 203f traduziria <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:26b</a>: … até no ato de declarar justo (cf. o genitivo absoluto de Polemon Soph . B 14 Reader <span class=\"greek\">καὶ</span> <span class=\"greek\">Δάτιδος</span> <span class=\"greek\">ἀποπλέοντος</span> =embora Dátis estivesse partindo de navio). Em fórmulas que expressam desejo: <span class=\"greek\">ὄφελον</span> <span class=\"greek\">καί</span> quem dera, oxalá <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:12</a>. Em ligação com um comparativo: <span class=\"greek\">κ</span>. <span class=\"greek\">περισσότερον</span> <span class=\"greek\">προφήτου</span> alguém ainda maior que um profeta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:9</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">μείζονα</span> <span class=\"greek\">ποιήσει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:12</a>.</p><p class=\"entry-text\">ⓒ Em períodos de contraste, <span class=\"greek\">καί</span> aparece de diversas maneiras, às vezes nos dois membros da comparação e frequentemente com aparente redundância para nossa compreensão <span class=\"greek\">καθάπερ</span> … , <span class=\"greek\">οὕτως</span> <span class=\"greek\">καί</span> assim como … assim também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:11</a>. <span class=\"greek\">ὥσπερ</span> … , <span class=\"greek\">οὕτως</span> <span class=\"greek\">καί</span> ( Hyperid . 1, 2, 5–8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:19</a> ; 11:30f ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:12</a> ; 15:22 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:29</a>. <span class=\"greek\">ὡς</span> … , <span class=\"greek\">οὕτως</span> <span class=\"greek\">καί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:15</a>, 18. <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">τρόπον</span> … , <span class=\"greek\">οὕτως</span> <span class=\"greek\">καί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:8</a>. — <span class=\"greek\">οὕτως</span> <span class=\"greek\">καί</span> assim também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:11</a>. <span class=\"greek\">ὡσαύτως</span> <span class=\"greek\">καί</span> do mesmo modo também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:25</a>. <span class=\"greek\">ὁμοίως</span> <span class=\"greek\">καί</span> ( Jos. , Bell. 2, 575 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:11</a> ; Jd 8. <span class=\"greek\">ὡς</span> <span class=\"greek\">καί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:17</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:7</a> ; 9:5. <span class=\"greek\">καθὼς</span> <span class=\"greek\">καί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:7</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:12</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:14</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:17</a>. <span class=\"greek\">καθάπερ</span> <span class=\"greek\">καί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:6</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:14</a>. — <span class=\"greek\">καί</span> também pode ocorrer isoladamente no segundo membro, com o sentido de «assim também, do mesmo modo». <span class=\"greek\">ὡς</span> … <span class=\"greek\">καί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:10</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.51\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:51</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:9</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:20</a>. <span class=\"greek\">καθὼς</span> … <span class=\"greek\">καί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:31</a> variante de leitura ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.57\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:57</a> ; 13:15 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.49\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:49</a>. — <span class=\"greek\">οἷος</span> … , <span class=\"greek\">τοιοῦτος</span> <span class=\"greek\">καί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.48\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:48</a>. Depois de um comparativo <span class=\"greek\">ὅσῳ</span> <span class=\"greek\">καί</span> tanto mais também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:6</a>. <span class=\"greek\">καί</span> ocorre em ambos os membros da comparação (ver Kühner-G. II 256; 2 Macc 2:10 ; 6:14 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:13</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:14</a>. <span class=\"greek\">καθὼς</span> <span class=\"greek\">καὶ</span> … <span class=\"greek\">οὕτως</span> <span class=\"greek\">καί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:13</a> ( cf. Hyperid . 1, 40, 20–25 <span class=\"greek\">ὥσπερ</span> <span class=\"greek\">καὶ</span> … <span class=\"greek\">οὕτω</span> <span class=\"greek\">καί</span> ; 3, 38).</p><p class=\"entry-text\">ⓓ com expressões que introduzem causa ou resultado, também aqui em grau considerável pleonástico <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">καί</span> por essa razão (também) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:49</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:18</a>. <span class=\"greek\">διὸ</span> <span class=\"greek\">καί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:35</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:29</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:22</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:12</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">καί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:9</a>. <span class=\"greek\">ὥστε</span> <span class=\"greek\">καί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:19</a> (mas essa passagem talvez pertença à subdivisão b). <span class=\"greek\">ὅθεν</span> <span class=\"greek\">καί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:25</a> ; 11:19.</p><p class=\"entry-text\">ⓔ após um interrogativo (como em Tucídides, Xenofonte e outros ; ver Kühner-G. II 255. Ver também B-D-F § 442, 14 ) afinal, ainda <span class=\"greek\">ἱνατί</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γῆν</span> <span class=\"greek\">καταργεῖ</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:7</a>. <span class=\"greek\">τί</span> <span class=\"greek\">καί</span>; ( Hyperid . 3, 14 <span class=\"greek\">τί</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀδικεῖ</span>; que espécie de injustiça, então, ele comete?) <span class=\"greek\">τί</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐλπίζει</span>; por que ele ainda (precisa) esperar? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:24</a>. variante de leitura <span class=\"greek\">τί</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">βαπτίζονται</span>; por que são batizados (afinal)? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:29</a> ; cf. vs. 30.</p><p class=\"entry-text\">ⓕ empregado com um relativo, confere frequentemente maior autonomia à oração relativa seguinte: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:14</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:30</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:2</a> variante de leitura ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:3</a>, 11 ; 7:45 ; 10:39 ; 11:30 ; 12:4 ; 13:22 ; 28:10 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:24</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:23</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:10</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:29</a> al. ⓖ empregado pleonasticamente com preposições <span class=\"greek\">α</span>. <span class=\"greek\">μετά</span> ( BGU 412, 6 <span class=\"greek\">μετὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">υἱοῦ</span> ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:3</a>. <span class=\"greek\">β</span>. <span class=\"greek\">σύν</span> (inscrições em PASA III 612; PFay 108; BGU 179, 19; 515, 17) 1 Cl 65:1 .— Dssm. , NB 93 ( BS 265f). ⓗ com nomes duplos: <span class=\"greek\">ὁ</span> <span class=\"greek\">καί</span>, «também chamado …» (o exemplo mais antigo está num fragmento de Ctésias : 688 Fgm. 15, 51 p. 469, 23 Jac. <span class=\"greek\">῏Ωχος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Δαρειαῖος</span> [ver Hatch 141]; OGI 565; 574; 583; 589; 603; 604; 620; 623; 636; POxy 45; 46; 54; 101; 485; 1279; PFay 30; BGU 22, 25; 36, 4; Jos. , Ant. 1, 240 ; 5, 85 ; 12 , 285 ; 13, 320; 18, 35. Material adicional em WSchmid, Der Atticismus III 1893, 338; Dssm. , B 181ff [ BS 313–17]. Bibliografia em B-D-F § 268, 1 ) <span class=\"greek\">Σαῦλος</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Παῦλος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:9</a>. <span class=\"greek\">Ἰγνάτιος</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Θεοφόρος</span> sobrescrito de todas as cartas de Inácio ⓘ com outras partículas <span class=\"greek\">α</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">γάρ</span> pois (ver <span class=\"greek\">γάρ</span> 1b).— <span class=\"greek\">καὶ</span> <span class=\"greek\">γὰρ</span> … <span class=\"greek\">ἀλλά</span> (ou «admitindo que …, mas» ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:4</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:27</a>. — <span class=\"greek\">καὶ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">οὐ</span>(<span class=\"greek\">κ</span> ): nem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:9</a> ; pois nem mesmo … <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:10</a>. <span class=\"greek\">β</span>. <span class=\"greek\">καί</span> <span class=\"greek\">γε</span> (sem palavra intermediária [ em contraste com o grego mais antigo, por exemplo Pla ., Phd. 58d; Rep. 7, 531a]: Hippocr ., Septim. 9, VII 450 Littré; Cornutus p. 40, 12; <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 13, 2; Rhetor Apsines [III a.d. ] p. 332, 17 Hammer; TestReub 4:4 al. ; sempre correspondente a גָּם em Teodocião [DBarthélemy, Les devanciers d’Aquila ’63, 31ff]), valor atenuado: (se) ao menos, pelo menos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:42</a> variante de leitura ; intensivo: com efeito, de fato ( Jos. Ant 29, 19) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:18</a> ( <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:2</a> variante de leitura ; Mel. , P. 30, 207); Hm 8:5 ; 9:9 . <span class=\"greek\">καί</span> <span class=\"greek\">γε</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μακράν</span> = e de fato Deus não está longe <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:27</a>. —Kühner-G. II 176b; Schwyzer II 561; B-D-F § 439, 2 ; Rdm. 2 35–37. <span class=\"greek\">γ</span>. <span class=\"greek\">καὶ</span> … <span class=\"greek\">δέ</span>: e também, mas também (ver <span class=\"greek\">δέ</span> 5b). <span class=\"greek\">δ</span>. <span class=\"greek\">καίτοι</span> ( Il. 13, 267 et al. , ins , pap ; 4 Macc 2:6 ; 5:18 ; 7:13 ; Ath. 8, 1 al. ; Mel. , P. 58, 422) partícula (B-D-F § 425, 1 ; 450, 3 ; Rob. 1129 e 1154) com verbo em forma finita ( Chion , Ep. 3, 1; Jos. Ant. 5, 78 ) contudo, por outro lado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:17</a>. Seguido de genitivo absoluto ( BGU 850, 4 [76 a.d. ] <span class=\"greek\">καίτοι</span> <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">σε</span> <span class=\"greek\">πολλὰ</span> <span class=\"greek\">ἐρωτήσαντος</span> ; 898, 26; Philo , Vi. Mos. 1, 20 ; Jos. , Ant. 2, 321 ; Ath. 19, 2; 25, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:3</a>. — <span class=\"greek\">καίτοι</span> <span class=\"greek\">γε</span> ou <span class=\"greek\">καί</span> <span class=\"greek\">τοι</span> <span class=\"greek\">γε</span> (desde Aristófanes, Ach. 611; mas sobretudo no grego posterior [ cf. Schwyzer II 561; MMeister, De Aiocho dial., Breslau diss. 1915 p. 31, 5]; Ps. - Pla ., Axioch. 364b; Jos. , Bell. 1, 7 , Ant. 5, 36 ; Epict . 3, 24, 90; Just ., A II, 11, 2; D . 7, 3; Ath. 3, 1; 22, 7; SIG 685, 76 e 82 [139 b.c. ]) embora, ainda que <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:2</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:17</a> variante de leitura ; Dg 8:3 . Seguido de particípio ( Jos. , C. Ap. 1, 230 ; Mel. , P. 58, 422) AcPt Ox 849 , 18.—Kühner-G. II 151f; B-D-F § 439, 1 ; 450, 3 .—Quanto a <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">κ</span>., <span class=\"greek\">δὲ</span> <span class=\"greek\">και</span>, <span class=\"greek\">ἐὰν</span> <span class=\"greek\">κ</span>., <span class=\"greek\">εἰ</span> <span class=\"greek\">κ</span>., <span class=\"greek\">ἢ</span> <span class=\"greek\">κ</span> ., ver <span class=\"greek\">ἀλλά</span> , <span class=\"greek\">δέ</span> , <span class=\"greek\">ἐάν</span> , <span class=\"greek\">εἰ</span> , <span class=\"greek\">ἤ</span> .—ERobson, KAI-Configurations in the Gk. NT , 3 vols. diss. Syracuse ’79. LfgrE sob o verbete <span class=\"greek\">καί</span> col. 1273f (bibliografia). DELG . M-M . EDNT .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0182-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Καϊάφας, α, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(também como variante de leitura <span class=\"greek\">Καϊαφᾶς</span> e <span class=\"greek\">Καϊφᾶς</span> ) Caifás ( Jos. , Ant. 18, 35 ; 95 ; Mel. , P. 93, 705 [ <span class=\"greek\">Καιφας</span> B ]), sumo sacerdote de 18 a 36 d.C., que desempenhou papel importante na condenação de Jesus. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:3</a>, 57 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:2</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.49\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:49</a> ; 18:13f, 24, 28 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:6</a> ; GEb 13, 74. Segundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:13</a> era genro de Anás (ver <span class=\"greek\">Ἅννας</span>, acepção 1).—Schürer II 216, 230; MStern em CRINT I 349–53.—KRengstorf, Rabb. Texte, ser. 1, vol. 3, ’33ff, p. 16f sobre Tos. Jeb. 1, 10. Sobre o nome, ver B-D-F § 37 ; Dalman , Gramm. 161, 2; EbNestle, Theol. Studien f. ThZahn, 1908, 251ff; FCBurkitt, The Syriac Forms of NT Proper Names (Proceed. of the Brit. Acad. 1911/12) 385; JJeremias, Jerusalem z. Zeit Jesu 3 ’63, 218–23; PWinter, On the Trial of Jesus ’61.— M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0182-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καίγε</h1><div class=\"entry-meta\"><span>partícula; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">ver <span class=\"greek\">γέ</span>, seção b <span class=\"greek\">γ</span> ( cf. <span class=\"greek\">και</span>, seção 2i <span class=\"greek\">β</span> ).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0182-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κάϊν, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">indeclinável ( קַיִן ; W-H. registram <span class=\"greek\">Καίν</span> ; LXX ; En 22:7 ; Philo ; TestBenj 7:5 ; TestAbr A 13 p. 92, 6 [Stone p. 32]; ApcMos , Philo ; Just ., D . 99, 3.—Em Josefo , Ant. 1, 52 ; 65 f; 57 <span class=\"greek\">Κάις</span>, <span class=\"greek\">Κάιος</span>, <span class=\"greek\">Κάιν</span> ) Caim, filho de Adão ( Gen 4:1ff ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:4</a> ; 1J 3:12 ; Jd 11 ; 1 Cl 4:1ff .—NDahl, in Apophoreta ( Haenchen Festschr. ) ’64, 70–84; PBretscher, Cain, Come Home! ’76; JReeves, Heralds of That Good Realm ’96, 1100f, n. 89 sobre o patrimônio de Caim na tradição. Ver também <span class=\"greek\">Ἅβελ</span> .— TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0182-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Καϊνάμ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">indeclinável ( <span class=\"greek\">Καϊνάν</span> , hebraico קֵינָן Gen 5:9 ) Cainã, na genealogia de Jesus.</p><p class=\"entry-text\">① filho de Arfaxade ( LXX Gen 10:24 ; 11:12 ; 1 Ch 1:18 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:36</a>. O nome não consta em P 75 D .</p><p class=\"entry-text\">② filho de Enos ( Gen 5:9ff. — Jos. , Ant. 1, 79 ; 84 <span class=\"greek\">Καινᾶς</span>, <span class=\"greek\">ᾶ</span> ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:37</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0182-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καινίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver <span class=\"greek\">καινός</span> ; trágicos e outros ) renovar, tornar novo B 6:11 variante de leitura (em lugar de <span class=\"greek\">ἀνακ</span> .).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0182-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καινοποιέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver <span class=\"greek\">καινός</span> e <span class=\"greek\">ποιέω</span> ; Soph ., Polyb ., Lucian , também Is 61:4 Sym; Jos, Just ., A I, 61, 1) renovar, fazer novo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:5</a>, variante de leitura</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0182-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καινός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( Aeschyl ., Hdt. +; ins , pap , LXX , TestSol ; TestAbr A 7 p. 84, 27 [Stone p. 16]; Test12Patr ; JosAs 14:13 e 15; Philo , Joseph ., Just ., Mel. ) comparativo <span class=\"greek\">καινότερος</span> ; sentido primário «novo».</p><p class=\"entry-text\">① relativo ao que existe há pouco tempo: novo, ainda não usado ( X. , Hell. 3, 4, 28; PGM 36, 265; Judg 15:13 ; 2 Km 6:3 ; 4 Km 2:20 ) <span class=\"greek\">ἀσκοί</span> odres ( Josh 9:13 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:17</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:22</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:38</a>. <span class=\"greek\">ἱμάτιον</span> ( Artem . 2, 3 p. 86, 3; 3 Km 11:29f ) versículo 36. <span class=\"greek\">μνημεῖον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.60\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:60</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.41\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:41</a> (com <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">οὐδέπω</span> <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">τεθειμένος</span> acrescentado). <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span> . o remendo novo= <span class=\"greek\">πλήρωμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:21</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:36</a>. <span class=\"greek\">καινὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παλαιά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.52\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:52</a> ( talvez com referência a moedas; cf. PGrenf II , 74, 9; 77, 7f).</p><p class=\"entry-text\">② relativo ao que antes não se apresentava: desconhecido, estranho, extraordinário, podendo implicar algo maravilhoso ou inaudito ( Pla ., Apol. 24c; X. , Mem. 1, 1, 1 <span class=\"greek\">ἕτερα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">καινὰ</span> <span class=\"greek\">δαιμόνια</span> ; Just ., A I, 15, 9; Orig ., C. Cels. 1 58, 15) <span class=\"greek\">διδαχή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:27</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:19</a>. <span class=\"greek\">ἐντολή</span> ( <span class=\"greek\">κ</span>. <span class=\"greek\">νόμος</span> : Menand ., Fgm. 238, 3 Kö.; Diod S 13, 34, 6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:34</a> ; 1J 2:7f (Polyaenus 2, 1, 13 <span class=\"greek\">οὐ</span> <span class=\"greek\">καινοὺς</span> <span class=\"greek\">νόμους</span> … <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">παλαιούς</span> ); 2J 5. <span class=\"greek\">ὄνομα</span> ( Is 62:2 ; 65:15 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:17</a> (aqui com <span class=\"greek\">ὸ̔</span> <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">οἶδεν</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λαμβάνων</span> , talvez como antídoto contra a magia hostil); 3:12. <span class=\"greek\">ᾠδή</span> 5:9 ( Ps 143:9 ; cf. Is 42:10 ; Ps 32:3; 39:4. — Philo , Vi. Cont. 80 <span class=\"greek\">ὕμνος</span> <span class=\"greek\">κ</span> . [ opp. <span class=\"greek\">ἀρχαῖος</span> ]); 14:3. <span class=\"greek\">γλῶσσαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:17</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">γένος</span> referindo-se aos cristãos Dg 1 . <span class=\"greek\">θεώρημα</span> AcPl Ox 6 , 1f ( <span class=\"greek\">διήγημα</span> Aa I, 241, 11). <span class=\"greek\">θέαμα</span> GJs 19:2f ( Mel. , P. 19, 127). Cristo como <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἄνθρωπος</span> o novo tipo de ser humano IEph 20:1 . <span class=\"greek\">ἢ</span> <span class=\"greek\">λέγειν</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἀκούειν</span> <span class=\"greek\">τι</span> <span class=\"greek\">καινότερον</span> ou ouvir ou dizer algo inteiramente novo (= «a última novidade») <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:21</a> (ver Kühner-G. II 306f; Norden, Agn. Th. 333ff [mas ver HAlmqvist, Plutarch u. d. NT ’46, 79f, com referência a Plut .]; B-D-F § 244, 2 ; Rdm. 70 e ver Demóstenes . 4, 10 <span class=\"greek\">ὦ</span> <span class=\"greek\">ἄνδρες</span> <span class=\"greek\">Ἀθηναῖοι</span> … <span class=\"greek\">λέγεταί</span> <span class=\"greek\">τι</span> <span class=\"greek\">καινόν</span>; <span class=\"greek\">γένοιτ</span>’ <span class=\"greek\">ἄν</span> <span class=\"greek\">τι</span> <span class=\"greek\">καινότερον</span> … ; também Teofrasto ., Char. 8, 2; BGU 821, 6 [II a.d. ] <span class=\"greek\">ὅταν</span> <span class=\"greek\">ᾖ</span> <span class=\"greek\">τι</span> <span class=\"greek\">καινότερον</span>, <span class=\"greek\">εὐθέως</span> <span class=\"greek\">σοι</span> <span class=\"greek\">δηλώσω</span> ; Simplicius , Coroll. De Tempore, em Aristóteles ., Phys. p. 788, 36ff <span class=\"greek\">καινοτέραν</span> <span class=\"greek\">ἐβάδισεν</span> <span class=\"greek\">ὁδόν</span> =trilhou um caminho bastante novo [de interpretação]; Jos. , Ant. 14, 104 ; Iren. 1, 18, 1 [ Harv. I 169, 3]).</p><p class=\"entry-text\">③ relativo ao que é recente em contraste com algo antigo: novo</p><p class=\"entry-text\">ⓐ sem implicar crítica ao antigo ( Herodas 4, 57 <span class=\"greek\">καινὴ</span> <span class=\"greek\">Ἀθηναίη</span> ; Lucian , M. Peregr. 12 <span class=\"greek\">κ</span>. <span class=\"greek\">Σωκράτης</span> ): referindo-se ao Filho de Deus ou Logos, que é antigo e novo simultaneamente Hs 9, 12, 1ff ; Dg 11:4 .</p><p class=\"entry-text\">ⓑ no sentido de que o antigo se tornou obsoleto e deve ser substituído pelo novo. Nesse caso, o novo é, em regra, qualitativamente superior ao antigo <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">διαθήκη</span> a nova aliança ou declaração ( Jer 38:31 ; Just ., D . 11, 4 al. ; Did. , Gen. 46, 4; 156, 5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:28</a> variante de leitura ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:24</a> variante de leitura ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:20</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:25</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:6</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:8</a> ( Jer 38:31 ), 13 ; 9:15. <span class=\"greek\">κ</span>. <span class=\"greek\">νόμος</span> (Timocles Com. [IV b.c. ] Fgm. 32, 4 <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">νόμον</span> <span class=\"greek\">τ</span>. <span class=\"greek\">καινόν</span> ; Just ., D . 12, 3; Mel. , P. 7, 46) B 2:6 . <span class=\"greek\">λαὸς</span> <span class=\"greek\">κ</span> . 5:7; 7:5; cf. 15:7.—Especialmente em uso escatológico <span class=\"greek\">κ</span>. <span class=\"greek\">οὐρανοί</span>, <span class=\"greek\">κ</span>. <span class=\"greek\">γῆ</span> ( Is 65:17 ; 66:22 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:13</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:1</a> ; <span class=\"greek\">Ἰερουσαλὴμ</span> <span class=\"greek\">καινή</span> versículo 2 ; 3:12. <span class=\"greek\">καινὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ποιεῖν</span> 21:5. <span class=\"greek\">καινὸν</span> <span class=\"greek\">πίνειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">γένημα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀμπέλου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:29</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:25</a>. —Referindo-se à renovação de uma pessoa convertida <span class=\"greek\">κ</span>. <span class=\"greek\">ἄνθρωπος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:24</a> ; Dg 2:1 . <span class=\"greek\">κ</span>. <span class=\"greek\">κτίσις</span> uma nova criatura <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:17a</a> ; cf. 17b ( Ps. - Pla ., Axioch. 11 p. 370e <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀσθενείας</span> <span class=\"greek\">ἐμαυτὸν</span> <span class=\"greek\">συνείλεγμαι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">γέγονα</span> <span class=\"greek\">καινός</span> =da fraqueza me recompus e me tornei novo; cf. Orig ., C. Cels. 6, 67, 33); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:15</a> ; cf. B 16:8 . Todos os cristãos em conjunto são apresentados como <span class=\"greek\">κ</span>. <span class=\"greek\">ἄνθρωπος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:15</a>. —RHarrisville, The Concept of Newness in the NT , ’60; GSchneider, <span class=\"greek\">Καινὴ</span> <span class=\"greek\">Κτίσις</span> (Paul and background), diss. Trier, ’59, Neuschöpfung oder Wiederkehr? ’61. Qumran: DSwanson, A Covenant Just Like Jacob’s, The Covenant of 11QT 29 and Jeremiah’s New Covenant: New Qumran Texts and Studies, ed. GBrooke/FMartínez ’94, 273–86.— B. 957. Schmidt, Syn. II 94–123. DELG . M-M . EDNT . TW . Ver <span class=\"greek\">νεό</span> .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0182-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καινότης, ητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(desde Tucídides 3, 38, 5; Plut ., Pericl. 13, 5; Lucian , Tyrannic. 22; 3 Km 8:53 a; Ezk 47:12 ; Philo , Vi. Cont. 63) novidade com conotação de algo extraordinário ( <span class=\"greek\">καινός</span> 2) referindo-se a uma estrela IEph 19:2 . Segundo um hebraísmo, o substantivo corresponde a um adjetivo <span class=\"greek\">κ</span>. <span class=\"greek\">πνεύματος</span> = <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">καινόν</span> um espírito novo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:6</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ζωῆς</span> uma vida nova 6:4 ; cf. IEph 19:3 (para bibliografia, ver <span class=\"greek\">παλιγγενεσία</span>, acepção 2). <span class=\"greek\">κ</span>. <span class=\"greek\">ἐλπίδος</span> uma nova esperança IMg 9:1 .— DELG sob o verbete <span class=\"greek\">καινός</span> . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0182-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καινοφωνία</h1><div class=\"entry-meta\"><span>remissão lexical</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">ver <span class=\"greek\">κενοφωνία</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0182-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καινῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">advérbio de <span class=\"greek\">καινός</span> ( OGI 669, 46; 49; Mel. , P. 57, 416) de modo novo, recentemente <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">κ</span> . (com <span class=\"greek\">ἐγένετο</span> subentendido) e isso não constituía novidade 1 Cl 42:5 . <span class=\"greek\">καινῶς</span> (<span class=\"greek\">τ</span>. <span class=\"greek\">θεὸν</span>) <span class=\"greek\">σεβόμενοι</span> adorando a Deus de maneira nova PtK 2 p. 15, 3; cf. 8.</p></section></article>\n"};
